body:
As stated in #46, SerialPortReader fails to kill Isolate on the "onPause"` event and creates a new one on the "onResume" event.
So, Isolates increase infinitely.

Below is the example code to reproduce the problem.
You'll see the increased Isolates in the call stack pane, as in the picture.

I'm not sure, but the onPause and onResume events are unnecessary,
because the serial port can buffer input data.

Or, if SerialPortReader needs to handle resume/pause events, 
`_isolate?.kill(priority: Isolate.immediate);` also works well.

```dart
import 'dart:typed_data';

import 'package:libserialport/libserialport.dart';

// ignore_for_file: avoid_print

void main() async {
  print('Available ports:');
  var i = 0;
  for (final name in SerialPort.availablePorts) {
    final sp = SerialPort(name);
    print('${++i}) $name');
    print('\tDescription: ${sp.description}');
    print('\tManufacturer: ${sp.manufacturer}');
    print('\tSerial Number: ${sp.serialNumber}');
    print('\tProduct ID: 0x${sp.productId!.toRadixString(16)}');
    print('\tVendor ID: 0x${sp.vendorId!.toRadixString(16)}');
    sp.dispose();
  }

  final _port = SerialPort("COM3");

  final config = SerialPortConfig();
  config.baudRate = 9600;
  config.bits = 8;
  config.parity = 0;
  _port.config = config;
  _port.openRead();

  final _reader = SerialPortReader(_port);

  final stream = _reader.stream;

  await for (var data in testFunc(stream)) {
    print(data);
  }
}

Stream<String> testFunc(Stream<Uint8List> stream) async* {
  await for (var data in stream) {
    final s = String.fromCharCodes(data);
    yield s; // this emits the onPause event but SerialPortReader can't kill Isolate properly
  }
}

```

![screenshot](https://github.com/jpnurmi/libserialport.dart/assets/56193/3101b4c5-cab8-4c38-a8b3-fe7a46744d95)

### Brief
We can get final flow value from excess[sink] in the last step.
- P0: `excess[x] == in_flow[x] - out_flo[x]` for all node. // definition
- P1: `out_flow[sink] == 0` at any time. // push will never be run on sink node
- P2: `excess[sink] == in_flow[sink]`

### Verification
- I have verified with [this problem](https://onlinejudge.u-aizu.ac.jp/problems/GRL_6_A)
``` code
#include <stdio.h>
#include <vector>

const int INF = 100000000;

int V, E;
std::vector<std::vector<int>> capacity;
std::vector<std::vector<int>> flow;
std::vector<int> height;

void input() {
    scanf("%d%d", &V, &E);
    capacity.resize(V, std::vector<int>(V));
    flow.resize(V, std::vector<int>(V));
    for (int i = 0; i < E; ++i) {
        int u, v, c;
        scanf("%d%d%d", &u, &v, &c);
        capacity[u][v] = c;
    }
}

int source, destination;
std::vector<int> excess;

void push(int x, int y) {
    int d = std::min(excess[x], capacity[x][y] - flow[x][y]);
    flow[x][y] += d;
    flow[y][x] = -flow[x][y];
    excess[x] -= d;
    excess[y] += d;
}

void initialize() {
    height.resize(V);
    height[source] = V;
    excess.resize(V);
    excess[source] = INF;
    for (int i = 0; i < V; ++i) {
        if (capacity[source][i] > 0) {
            push(source, i);
        }
    }
}

std::vector<int> get_highest_excesses() {
    int highest = -1;
    std::vector<int> ans;
    for (int i = 0; i < V; ++i) {
        if (i == source || i == destination || excess[i] == 0) {
            continue;
        }
        if (height[i] > highest) {
            highest = height[i];
            ans.clear();
            ans.push_back(i);
        } else if (height[i] == highest) {
            ans.push_back(i);
        }
    }
    return ans;
}

void lift(int x) {
    int minimum_height = INF;
    for (int i = 0; i < V; ++i) {
        if (capacity[x][i] > flow[x][i]) {
            minimum_height = std::min(minimum_height, height[i]);
        }
    }
    height[x] = minimum_height + 1;
}

int maximum_flow() {
    initialize();
    std::vector<int> highest_excesses;
    while (!(highest_excesses = get_highest_excesses()).empty()) {
        for (int x: highest_excesses) {
            bool pushed = false;
            for (int y = 0; y < V; ++y) {
                if (height[x] == height[y] + 1 && capacity[x][y] > flow[x][y]) {
                    push(x, y);
                    pushed = true;
                }
            }
            if (!pushed) {
                lift(x);
                break;
            }
        }
    }
    return excess[destination];
}

int main() {
    input();
    source = 0;
    destination = V - 1;
    printf("%d\n", maximum_flow());
    return 0;
}
```

